System.register([],function(a,e){var r,i,s,t;return{setters:[],execute:function(){i=[(r=(a,e,r)=>({id:a,kk:e,ru:r}))("knowing","Білу","Знание"),r("applying","Қолдану","Применение"),r("reasoning","Пайымдау","Рассуждение")],a("t",s=[{id:"modo",short:"ББЖМ",kk:"ББЖМ (МОДО)",ru:"МОДО",org:"Ұлттық тестілеу орталығы",grades:[4,9],areas:[{id:"reading",kk:"Оқу сауаттылығы",ru:"Читательская грамотность",grades:[4,9],reading:!0,domains:[r("find","Ақпаратты табу","Поиск информации"),r("infer","Түсіну және қорытынды","Понимание и вывод"),r("evaluate","Бағалау","Оценка")]},{id:"math",kk:"Математикалық сауаттылық",ru:"Математическая грамотность",grades:[4,9],domains:[r("number","Сандар және есептеу","Числа и вычисления"),r("algebra","Өрнектер мен теңдеулер","Выражения и уравнения"),r("geometry","Геометрия және өлшеу","Геометрия и измерения"),r("data","Деректер және ықтималдық","Данные и вероятность")]},{id:"science",kk:"Жаратылыстану сауаттылығы",ru:"Естественнонаучная грамотность",grades:[4,9],domains:[r("life","Тірі табиғат","Живая природа"),r("physical","Физикалық құбылыстар","Физические явления"),r("chemistry","Заттар","Вещества"),r("earth","Жер және ғарыш","Земля и космос")]}],mock:{questions:20,minutes:40},scale:"percent",pass:50,about:{kk:["Білім алушылардың білім жетістіктерін мониторингілеу — 4 және 9-сыныптарда өтетін ұлттық зерттеу. Мақсаты — оқушының емес, мектеп пен білім жүйесінің нәтижесін бағалау.","Компьютерлік тест: бір дұрыс жауапты тапсырмалар, жиі мәтін, кесте не сурет негізінде. Пән білімі емес, оны өмірлік жағдайда қолдану тексеріледі."],ru:["Мониторинг образовательных достижений обучающихся — национальное исследование в 4 и 9 классах. Оценивает результаты школы и системы, а не отдельного ученика.","Компьютерный тест: задания с одним верным ответом, чаще на основе текста, таблицы или рисунка. Проверяется умение применять знания в жизни."]},tips:{kk:["Алдымен сұрақты, сосын мәтінді оқы — не іздеу керек екенін біл.","Кесте мен диаграммадағы өлшем бірліктерге назар аудар.","Уақытты бөл: бір тапсырмаға 2 минуттан аспасын."],ru:["Сначала прочитай вопрос, потом текст — знай, что искать.","Следи за единицами измерения в таблицах и диаграммах.","Распредели время: не больше 2 минут на задание."]},tint:["#10b981","#0f766e"]},{id:"mma",short:"ММА",kk:"ММА — мемлекеттік аттестаттау",ru:"Госаттестация школы",org:"Сапаны қамтамасыз ету комитеті",grades:[4,9,11],areas:[{id:"math",kk:"Математика",ru:"Математика",grades:[4,9,11],calculator:!1,domains:[r("number","Сандар","Числа"),r("algebra","Алгебра","Алгебра"),r("geometry","Геометрия","Геометрия"),r("data","Статистика","Статистика")]},{id:"kazakh",kk:"Қазақ тілі",ru:"Казахский язык",grades:[4,9,11],reading:!0,domains:[r("grammar","Грамматика","Грамматика"),r("vocab","Лексика","Лексика"),r("text","Мәтінмен жұмыс","Работа с текстом")]},{id:"russian",kk:"Орыс тілі",ru:"Русский язык",grades:[4,9,11],reading:!0,domains:[r("grammar","Грамматика","Грамматика"),r("orth","Орфография","Орфография"),r("text","Мәтінмен жұмыс","Работа с текстом")]},{id:"history",kk:"Қазақстан тарихы",ru:"История Казахстана",grades:[9,11],domains:[r("ancient","Ежелгі және ортағасыр","Древность и средние века"),r("khanate","Қазақ хандығы","Казахское ханство"),r("modern","Жаңа және қазіргі заман","Новое и новейшее время")]},{id:"science",kk:"Жаратылыстану",ru:"Естествознание",grades:[4],domains:[r("life","Тірі табиғат","Живая природа"),r("physical","Физикалық құбылыстар","Физические явления"),r("earth","Жер","Земля")]},{id:"physics",kk:"Физика",ru:"Физика",grades:[9,11],calculator:!0,domains:[r("mechanics","Механика","Механика"),r("thermo","Жылу","Теплота"),r("electric","Электр","Электричество"),r("optics","Оптика","Оптика")]},{id:"biology",kk:"Биология",ru:"Биология",grades:[9,11],domains:[r("cell","Жасуша","Клетка"),r("organism","Ағза","Организм"),r("ecology","Экология","Экология")]},{id:"chemistry",kk:"Химия",ru:"Химия",grades:[9,11],domains:[r("matter","Зат құрылысы","Строение вещества"),r("reactions","Реакциялар","Реакции"),r("organic","Органика","Органика")]},{id:"geography",kk:"География",ru:"География",grades:[9,11],domains:[r("physical","Физикалық география","Физическая география"),r("kz","Қазақстан географиясы","География Казахстана"),r("economic","Экономикалық география","Экономическая география")]}],mock:{questions:20,minutes:40},scale:"percent",pass:50,about:{kk:["Білім беру ұйымын мемлекеттік аттестаттау кезінде оқушылардың білімі тексеріледі: 4, 9 және 11-сыныптар, бағдарламадағы негізгі пәндер бойынша.","Тест бір немесе бірнеше дұрыс жауапты тапсырмалардан тұрады. Нәтиже мектептің аттестаттаудан өтуіне әсер етеді (өту шегі — баптауға болады)."],ru:["При государственной аттестации организации образования проверяются знания учеников 4, 9 и 11 классов по основным предметам программы.","Тест из заданий с одним или несколькими верными ответами. Результат влияет на прохождение школой аттестации (порог настраивается)."]},tips:{kk:["Бағдарламаның барлық тарауын қайтала — тест оқулық бойынша.","«Бірнеше жауап» тапсырмасында әр нұсқаны жеке тексер.","Сынақ емтиханды уақытпен тапсыр — нақты жағдайға үйрен."],ru:["Повтори все разделы программы — тест по учебнику.","В заданиях с несколькими ответами проверяй каждый вариант.","Пиши пробный экзамен на время — привыкай к реальным условиям."]},tint:["#6366f1","#4338ca"]},{id:"pisa",short:"PISA",kk:"PISA",ru:"PISA",org:"ЭЫДҰ (OECD)",grades:[9,10],areas:[{id:"reading",kk:"Оқу сауаттылығы",ru:"Читательская грамотность",grades:[9,10],reading:!0,domains:[r("locate","Ақпаратты табу","Поиск информации"),r("understand","Түсіну","Понимание"),r("reflect","Бағалау және ой толғау","Оценка и рефлексия")]},{id:"math",kk:"Математикалық сауаттылық",ru:"Математическая грамотность",grades:[9,10],calculator:!0,domains:[r("quantity","Шама","Количество"),r("change","Өзгеріс және тәуелділік","Изменения и зависимости"),r("space","Кеңістік және пішін","Пространство и форма"),r("uncertainty","Деректер және кездейсоқтық","Неопределённость и данные")]},{id:"science",kk:"Жаратылыстану-ғылыми сауаттылық",ru:"Естественнонаучная грамотность",grades:[9,10],domains:[r("explain","Құбылыстарды ғылыми түсіндіру","Научное объяснение явлений"),r("inquiry","Зерттеуді бағалау және жоспарлау","Оценка и планирование исследования"),r("data","Деректер мен дәлелдерді түсіндіру","Интерпретация данных и доказательств")]},{id:"finance",kk:"Қаржылық сауаттылық",ru:"Финансовая грамотность",grades:[9,10],calculator:!0,domains:[r("money","Ақша және төлем","Деньги и платежи"),r("planning","Жоспарлау","Планирование"),r("risk","Тәуекел және пайда","Риск и доходность"),r("landscape","Қаржы ортасы","Финансовая среда")]}],cognitive:[r("formulate","Тұжырымдау","Формулировать"),r("employ","Қолдану","Применять"),r("interpret","Түсіндіру және бағалау","Интерпретировать")],mock:{questions:18,minutes:60},scale:"pisa",about:{kk:["Халықаралық білім алушыларды бағалау бағдарламасы — 15 жастағы оқушылар (9–10-сынып) 3 жыл сайын тапсырады. Мектеп бағдарламасын емес, білімді өмірде қолдана білуді тексереді.","Тапсырмалар «бірлік» түрінде: бір жағдаят (мәтін, кесте, график) және оған 2–5 сұрақ. Жауап түрлері: таңдау, күрделі таңдау (иә/жоқ), сан, ашық жауап. Нәтиже 1–6 деңгейлік шкаламен беріледі."],ru:["Международная программа оценки учащихся — 15-летние (9–10 класс), раз в 3 года. Проверяет не программу, а умение применять знания в жизни.","Задания объединены в «блоки»: одна ситуация (текст, таблица, график) и 2–5 вопросов. Типы ответов: выбор, сложный выбор (да/нет), число, открытый ответ. Результат — уровни 1–6."]},tips:{kk:["Ашық жауапта дәлел келтір: «өйткені…, деректе…».","Кестедегі санды қолдан — өз біліміңнен емес.","Күрделі таңдауда әр жолды жеке бағала."],ru:["В открытом ответе приводи довод: «потому что…, в данных…».","Опирайся на числа из таблицы, а не на свои знания.","В сложном выборе оценивай каждую строку отдельно."]},tint:["#0ea5e9","#2563eb"]},{id:"timss",short:"TIMSS",kk:"TIMSS",ru:"TIMSS",org:"IEA",grades:[4,8],areas:[{id:"math",kk:"Математика",ru:"Математика",grades:[4,8],calculator:!0,domains:[r("number","Сандар","Числа"),r("algebra","Алгебра","Алгебра"),r("geometry","Геометрия және өлшеу","Геометрия и измерения"),r("data","Деректер және ықтималдық","Данные и вероятность")]},{id:"science",kk:"Жаратылыстану",ru:"Естествознание",grades:[4,8],domains:[r("biology","Биология","Биология"),r("chemistry","Химия","Химия"),r("physics","Физика","Физика"),r("earth","Жер туралы ғылым","Науки о Земле")]}],cognitive:i,mock:{questions:24,minutes:45},scale:"timss",about:{kk:["Математика мен жаратылыстанудағы халықаралық зерттеу — 4 және 8-сыныптар, 4 жыл сайын. Мазмұн салалары мен ойлау деңгейлері (білу, қолдану, пайымдау) бойынша бағалайды.","Тапсырмалардың жартысына жуығы — таңдау, қалғаны — өз жауабыңды жазу. Халықаралық эталондар: 400 (төмен), 475 (орташа), 550 (жоғары), 625 (озық)."],ru:["Международное исследование по математике и естествознанию — 4 и 8 классы, раз в 4 года. Оценивает по предметным областям и уровням мышления (знание, применение, рассуждение).","Около половины заданий — выбор ответа, остальные — свой ответ. Международные ориентиры: 400 (низкий), 475 (средний), 550 (высокий), 625 (продвинутый)."]},tips:{kk:["Пайымдау тапсырмасында шешу жолын қысқа жаз.","Сурет пен кестеде берілгенді белгіле.","Жауапты шамамен бағалап тексер: мағынасы бар ма?"],ru:["В заданиях на рассуждение кратко записывай ход решения.","Отмечай данные на рисунке и в таблице.","Проверяй ответ прикидкой: есть ли смысл?"]},tint:["#f59e0b","#ea580c"]},{id:"icils",short:"ICILS",kk:"ICILS",ru:"ICILS",org:"IEA",grades:[8],areas:[{id:"cil",kk:"Компьютерлік-ақпараттық сауаттылық",ru:"Компьютерная и информационная грамотность",grades:[8],domains:[r("use","Компьютерді қолдануды түсіну","Понимание работы компьютера"),r("gather","Ақпарат жинау","Сбор информации"),r("produce","Ақпарат жасау","Создание информации"),r("communicate","Цифрлық қарым-қатынас","Цифровая коммуникация")]},{id:"ct",kk:"Есептеуіш ойлау",ru:"Вычислительное мышление",grades:[8],domains:[r("conceptualize","Мәселені түсіну","Осмысление задачи"),r("operationalize","Шешімді құру","Построение решения")]}],mock:{questions:16,minutes:40},scale:"icils",about:{kk:["Компьютерлік және ақпараттық сауаттылықтың халықаралық зерттеуі — 8-сынып. Оқушы шынайы компьютер ортасында жұмыс істейді: пошта, браузер, файлдар, кесте.","Тапсырмалар интерактивті: қауіпті хатты табу, сенімді сайтты таңдау, файлды дұрыс жерге салу, алгоритм қадамдарын ретке келтіру. Нәтиже 1–4 деңгеймен беріледі."],ru:["Международное исследование компьютерной и информационной грамотности — 8 класс. Ученик работает в настоящей компьютерной среде: почта, браузер, файлы, таблицы.","Задания интерактивные: найти опасное письмо, выбрать надёжный сайт, разложить файлы, упорядочить шаги алгоритма. Результат — уровни 1–4."]},tips:{kk:["Хаттың жіберушісі мен сілтемесін тексер.","Жарнамалық нәтижені ресми дереккөзден ажырат.","Алгоритмді бір-бір қадаммен «орындап» көр."],ru:["Проверяй отправителя и ссылку в письме.","Отличай рекламный результат от официального источника.","Мысленно «выполни» алгоритм шаг за шагом."]},tint:["#8b5cf6","#6d28d9"]},{id:"pirls",short:"PIRLS",kk:"PIRLS",ru:"PIRLS",org:"IEA",grades:[4],areas:[{id:"reading",kk:"Оқу сауаттылығы",ru:"Читательская грамотность",grades:[4],reading:!0,domains:[r("retrieve","Мәтіннен ақпаратты табу","Нахождение информации"),r("infer","Қарапайым қорытынды","Простые выводы"),r("interpret","Түсіндіру және біріктіру","Интерпретация и обобщение"),r("evaluate","Мәтінді бағалау","Оценка текста")]}],mock:{questions:16,minutes:40},scale:"timss",about:{kk:["Оқу сауаттылығының халықаралық зерттеуі — 4-сынып, 5 жыл сайын. Екі түрлі мәтін: көркем (әңгіме) және ақпараттық (мақала, нұсқаулық).","Әр мәтінге 12–16 сұрақ: ақпаратты табу, қорытынды шығару, түсіндіру, бағалау. Жауаптың жартысы — өз сөзіңмен жазу. Эталондар: 400 / 475 / 550 / 625."],ru:["Международное исследование качества чтения — 4 класс, раз в 5 лет. Два вида текстов: художественный (рассказ) и информационный (статья, инструкция).","К каждому тексту 12–16 вопросов: найти информацию, сделать вывод, интерпретировать, оценить. Половина ответов — своими словами. Ориентиры: 400 / 475 / 550 / 625."]},tips:{kk:["Мәтінді толық оқып шық, сосын сұраққа көш.","Жауапты мәтіннен дәлелмен жаз.","Кейіпкердің сезімін оның іс-әрекетінен тап."],ru:["Сначала прочитай текст целиком, потом вопросы.","Подтверждай ответ словами из текста.","Чувства героя ищи в его поступках."]},tint:["#ec4899","#be185d"]}]),a("r",t=a=>s.find(e=>e.id===a)),a("n",(a,e)=>t(a).areas.find(a=>a.id===e))}}});